static class SlabEstimatorEngine {
 public static int Count(double width,double spacingMm,double coverMm){if(spacingMm<=0||double.IsNaN(spacingMm)||double.IsInfinity(spacingMm)||width*1000<=2*coverMm)throw new Exception("Check reinforcement spacing, width and cover.");return checked((int)Math.Ceiling((width-2*coverMm/1000)/(spacingMm/1000)-1e-10)+1);}
 public static SlabTakeoff Calculate(SlabScheduleRow row,string description,double shorter,double longer,int quantity,bool elevated,double edge,double cover,LengthConfiguration config,int longCont,int longEnd,int shortCont,int shortEnd,double adjacentShort,double adjacentLong,bool cantileverEdge=false){
  if(row==null||config==null)throw new Exception("Choose a slab schedule and material configuration.");config.Validate();if(adjacentShort<0||adjacentLong<0||double.IsNaN(adjacentShort+adjacentLong)||double.IsInfinity(adjacentShort+adjacentLong))throw new Exception("Adjacent spans must be blank or nonnegative finite lengths.");if(cover<0||double.IsNaN(cover)||double.IsInfinity(cover))throw new Exception("Cover must be nonnegative.");foreach(int n in new[]{longCont,longEnd,shortCont,shortEnd})if(n<0||n>2)throw new Exception("Support counts must be 0, 1 or 2.");if(longCont+longEnd>2||shortCont+shortEnd>2)throw new Exception("At most two opposite supports per direction.");
  var result=new SlabTakeoff{Schedule=row,GeometryBasis="Short "+shorter.ToString("0.00")+"m; long "+longer.ToString("0.00")+"m; cover "+cover.ToString("0.00")+"mm; over LONG support CONT/END="+longCont+"/"+longEnd+"; over SHORT CONT/END="+shortCont+"/"+shortEnd,Thickness=row.Thickness,Measures=SlabQuantities.Calculate(shorter,longer,row.Thickness,quantity,elevated,edge,cantileverEdge),Steel=new EstimateInput{Description=description,Beam=row.Mark,Length=shorter.ToString(CultureInfo.InvariantCulture)+" x "+longer.ToString(CultureInfo.InvariantCulture),Quantity=quantity.ToString(),Result=new BeamEstimate()}};
  double countWidth=0;int supportMultiplier=1;
  Action<SlabBar,string,double,int,bool> add=(bar,name,body,count,top)=>{if(bar==null||count==0)return;if(body<=0)throw new Exception("Cutoff leaves no positive bar body.");var v=config.Values(bar.Diameter,top);double ld=config.Rounded(v.Ld)/1000,cut=SlabCurtailment.Up25(body+2*ld);int grade=bar.Diameter<=12?config.GradeSmall:config.GradeLarge;double metres=cut*count*quantity;result.Steel.Result.Lines.Add(new EstimateLine{Part=name,Beam=row.Mark,Diameter=bar.Diameter,Grade=grade,PiecesPerBeam=count,CutLength=cut,Metres=metres,Kg=metres*EstimatorEngine.UnitMass(bar.Diameter),Formula=bar.ExplicitCount>0?supportMultiplier+" support(s) × "+bar.ExplicitCount+" entered bars = "+count+" pcs/unit; body "+(body*1000).ToString("0.00")+"mm + 2Ld "+(2000*ld).ToString("0.00")+"mm; final cut UP25mm":supportMultiplier+" support(s) x [ceil(("+(countWidth*1000).ToString("0.00")+"mm - 2 x "+cover.ToString("0.00")+"mm) / "+bar.SpacingMm.ToString("0.00")+"mm) + 1] = "+count+" pcs/unit; body "+(body*1000).ToString("0.00")+"mm + 2Ld "+(2000*ld).ToString("0.00")+"mm; final cut UP25mm"});};
  for(int direction=0;direction<2;direction++){double span=direction==0?shorter:longer,cross=direction==0?longer:shorter;int full=direction*2;countWidth=cross;supportMultiplier=1;var bar=row.Bars[full];if(bar!=null)add(bar,"Bottom "+(direction==0?"short FULL":"long FULL"),span,ManualSlabSchedule.Count(bar,cross,cover),false);bar=row.Bars[full+1];if(bar!=null)add(bar,"Bottom "+(direction==0?"short CURTAILED":"long CURTAILED"),SlabCurtailment.BottomMiddleBody(span),ManualSlabSchedule.Count(bar,cross,cover),false);}
  for(int direction=0;direction<2;direction++){double span=direction==0?shorter:longer,cross=direction==0?longer:shorter,neighbor=direction==0?adjacentShort:adjacentLong;int cont=direction==0?longCont:shortCont,end=direction==0?longEnd:shortEnd,index=direction==0?4:6;string support=direction==0?"LONG":"SHORT";if(neighbor<=0){neighbor=span;if(cont>0)result.Notes.Add("Over "+support+" support: adjacent span assumed equal to entered "+span.ToString("0.00")+"m. Override adjacent-span input for unequal panels.");}
   foreach(bool continuous in new[]{true,false}){int n=continuous?cont:end;var bar=row.Bars[index+(continuous?0:1)];if(n==0)continue;if(bar==null)throw new Exception("Selected "+support+" support type has no reinforcement in the selected schedule.");double strip=continuous?SlabCurtailment.TopContinuousBody(span,neighbor,0):SlabCurtailment.TopPanelExtension(span);countWidth=cross;supportMultiplier=n;add(bar,"Top over "+support+" "+(continuous?"CONT":"END"),strip,checked(n*ManualSlabSchedule.Count(bar,cross,cover)),true);var distribution=row.Bars[8];if(distribution!=null){countWidth=strip;add(distribution,"Top distribution "+support+" "+(continuous?"CONT":"END"),cross,checked(n*ManualSlabSchedule.Count(distribution,strip,cover)),true);}}}
  result.Notes.Add("Span basis: entered shorter/longer sides; no automatic support-width deduction. All cuts include 2 straight Ld allowances; no bent-up bars or automatic end hooks.");result.Notes.Add("Continuous-support bars include both panel extensions. Count each shared support once; reduce support count in the neighboring entry when already included here.");result.Notes.Add("Distribution is additional top-strip reinforcement perpendicular to top main bars. No automatic corner/overlap deductions; verify against slab detailing.");return result;
 }
}
