 public Control WorksSettings {get;private set;}
 internal List<double> WorksStockLengths {get{return new List<double>(stockLengths);}}
 internal void SetWorksStockLengths(List<double> lengths){stockLengths=CommercialBars.ParseLengths(CommercialBars.FormatLengths(lengths));Recalculate();}
 void ConfigureHelp(FlowLayoutPanel tools){string[] tips={"Pangalan o location ng takeoff entry.","Slab mark mula sa DXF o sa Manual reinforcement schedules. Thickness at reinforcement follow the selected schedule.","Haba ng shorter side ng ISANG panel, in metres.","Haba ng longer side ng ISANG panel, in metres.","Bilang ng magkakaparehong slab panels.","Default Elevated includes bottom forms. On gravel fill excludes bottom forms.","Exposed cantilever edge length for one panel. Disabled for ordinary elevated/gravel.","Automatic continuous support count from DXF.","Automatic end support count from DXF.","Automatic continuous support count from DXF.","Automatic end support count from DXF.","Neighbor span for unequal adjacent panels; blank uses current shorter side.","Neighbor span for unequal adjacent panels; blank uses current longer side.","Thickness from the selected DXF or manual schedule, millimetres.","Gross concrete = short x long x thickness/1000 x quantity. No automatic openings deduction.","Elevated: soffit area. Cantilever edge option adds side-edge forms. Gravel: no bottom forms.","Actual commercial rebar purchase weight, including computed lap steel and stock offcuts; no waste factor.","Shows missing inputs or calculation results."};for(int n=0;n<tips.Length;n++)grid.Columns[n].ToolTipText=tips[n];grid.RowsAdded+=(s,e)=>{for(int r=e.RowIndex;r<e.RowIndex+e.RowCount&&r<grid.Rows.Count;r++)for(int c=0;c<tips.Length;c++)grid.Rows[r].Cells[c].ToolTipText=tips[c];};help.SetToolTip(mode,"Summary = purchase totals. Detailed = source schedule, counts and cuts. Extensive = formulas, configured lengths and stock comparisons.");help.SetToolTip(cover,"Concrete cover used for bar-count spacing limits, in millimetres.");foreach(Control button in tools.Controls){if(button.Text=="Commercial lengths")help.SetToolTip(button,"Check only stock lengths available to buy. The least-waste choice is selected from the checked lengths.");if(button.Text=="Special cases (optional)")help.SetToolTip(button,"Choose elevated, gravel fill or cantilever-edge forms. Fields switch on/off automatically; support overrides are optional.");}}
 void Guard(){if(!AccessCodes.CanUseApp(2))throw new Exception("Renew estimator access to continue.");}
 static void Button(FlowLayoutPanel p,string label,Action action){var b=new Button{Text=label,AutoSize=true,Height=32};b.Click+=(s,e)=>{try{action();}catch(Exception x){MessageBox.Show(x.Message,"Slab Estimator");}};p.Controls.Add(b);}
 static ComboBox Select(FlowLayoutPanel p,string label,string[] values){var box=new FlowLayoutPanel{Width=165,Height=64,FlowDirection=FlowDirection.TopDown};box.Controls.Add(new Label{Text=label,Height=20});var c=new ComboBox{DropDownStyle=ComboBoxStyle.DropDownList,Width=155};c.Items.AddRange(values);c.SelectedIndex=0;box.Controls.Add(c);p.Controls.Add(box);return c;}
 static string Cell(DataGridViewRow r,int n){return Convert.ToString(r.Cells[n].Value).Trim();}static double Number(string value,string name){double n;if(!double.TryParse(value,NumberStyles.Float,CultureInfo.InvariantCulture,out n)||double.IsNaN(n)||double.IsInfinity(n))throw new Exception("Invalid "+name);return n;}static int Whole(string value,string name){int n;if(!int.TryParse(value,out n))throw new Exception("Enter whole "+name);return n;}
 void Resolve(){if(!storedProfile)configuration=CalculationStore.Resolve(double.Parse(fc.Text,CultureInfo.InvariantCulture),small.SelectedIndex==0?40:60,small.SelectedIndex==0?276:420,large.SelectedIndex==0?60:40,large.SelectedIndex==0?420:276);}
 void AddSource(string raw,string name){if(!ManualSlabSchedule.IsManual(raw))sourceAttachments.CaptureText(name,"Slab DXF",raw);raw=raw.Replace("\r\n","\n").Replace("\r","\n");var rows=ManualSlabSchedule.ReadSource(raw);if(rows.Any(r=>schedules.ContainsKey(r.Mark)))throw new Exception("Duplicate slab marks across source files; use unique identifiers.");foreach(var row in rows)schedules.Add(row.Mark,row);sourceFiles.Add(new[]{name,raw});UpdateLoadedDxf();var c=(DataGridViewComboBoxColumn)grid.Columns[1];foreach(var row in rows)c.Items.Add(row.Mark);}
 void UpdateLoadedDxf(){loadedDxf.Text="Reinforcement sources ("+sourceFiles.Count+"): "+string.Join("; ",sourceFiles.Select(file=>file[0]))+"\n"+schedules.Count+" slab marks available";help.SetToolTip(loadedDxf,string.Join("\n",sourceFiles.Select(file=>file[0])));}
 void ManageSources(){Guard();grid.EndEdit();var marks=sourceFiles.Select(file=>new HashSet<string>(ManualSlabSchedule.ReadSource(file[1]).Select(row=>row.Mark),StringComparer.OrdinalIgnoreCase)).ToList();int index=DxfSourceManager.ChooseRemoval(this,sourceFiles.Select(file=>file[0]).ToArray(),marks.Select(set=>grid.Rows.Cast<DataGridViewRow>().Count(row=>!row.IsNewRow&&set.Contains(Cell(row,1)))).ToArray());if(index<0)return;RemoveSourceAt(index);}
 internal void RemoveSourceAt(int index){if(index<0||index>=sourceFiles.Count)throw new ArgumentOutOfRangeException("index");var marks=sourceFiles.Select(file=>new HashSet<string>(ManualSlabSchedule.ReadSource(file[1]).Select(row=>row.Mark),StringComparer.OrdinalIgnoreCase)).ToList();filling=true;try{foreach(var row in grid.Rows.Cast<DataGridViewRow>().Where(row=>!row.IsNewRow&&marks[index].Contains(Cell(row,1))).ToList())grid.Rows.Remove(row);foreach(string mark in marks[index])schedules.Remove(mark);sourceFiles.RemoveAt(index);var combo=(DataGridViewComboBoxColumn)grid.Columns[1];combo.Items.Clear();foreach(string mark in schedules.Keys)combo.Items.Add(mark);}finally{filling=false;}UpdateLoadedDxf();Recalculate();}
 void LoadDxf(){LoadDxf(false);}
 void LoadDxf(bool replace){Guard();using(var d=new OpenFileDialog{Filter="Slab schedule DXF|*.dxf",Multiselect=true})if(d.ShowDialog(this)==DialogResult.OK){var originals=d.FileNames.Select(path=>PowSourceFiles.ReadFile(path,"Slab DXF")).ToList();var candidates=originals.Select(file=>new[]{file.Name,file.Text()}).ToList();var marks=new HashSet<string>(replace?Enumerable.Empty<string>():schedules.Keys,StringComparer.OrdinalIgnoreCase);foreach(var item in candidates)foreach(var row in SlabScheduleReader.Read(item[1]))if(!marks.Add(row.Mark))throw new Exception("Duplicate slab mark "+row.Mark);if(replace){filling=true;try{grid.Rows.Clear();schedules.Clear();sourceFiles.Clear();((DataGridViewComboBoxColumn)grid.Columns[1]).Items.Clear();}finally{filling=false;}}foreach(var item in candidates)AddSource(item[1],item[0]);foreach(var file in originals)sourceAttachments.Add(file);Recalculate();}}
 void SetSupportDefaults(DataGridViewRow row){SlabScheduleRow slab;if(!schedules.TryGetValue(Cell(row,1),out slab))return;filling=true;try{for(int d=0;d<2;d++){bool cont=slab.Bars[4+2*d]!=null,end=slab.Bars[5+2*d]!=null;row.Cells[7+2*d].Value=cont?(end?"1":"2"):"0";row.Cells[8+2*d].Value=end?(cont?"1":"2"):"0";}}finally{filling=false;}Recalculate();}
 public void Recalculate(){if(filling||grid==null)return;using(GridBatch.Suspend(this))RecalculateRows();}
 void RecalculateRows(){if(filling||grid==null)return;filling=true;try{Resolve();results.Clear();errors.Clear();foreach(DataGridViewRow row in grid.Rows){if(row.IsNewRow)continue;row.Tag=null;for(int n=13;n<18;n++)row.Cells[n].Value="";if(Enumerable.Range(0,4).All(n=>Cell(row,n)==""))continue;try{SlabScheduleRow slab;if(!schedules.TryGetValue(Cell(row,1),out slab))throw new Exception("Choose a slab mark");if(Cell(row,0)=="")throw new Exception("Enter description");var result=SlabEstimatorEngine.Calculate(slab,Cell(row,0),Number(Cell(row,2),"short side"),Number(Cell(row,3),"long side"),Whole(Cell(row,4),"quantity"),Cell(row,5)!="On gravel fill",Cell(row,6)==""?0:Number(Cell(row,6),"exposed edge"),(double)cover.Value,configuration,Whole(Cell(row,7),"long CONT count"),Whole(Cell(row,8),"long END count"),Whole(Cell(row,9),"short CONT count"),Whole(Cell(row,10),"short END count"),Cell(row,11)==""?0:Number(Cell(row,11),"adjacent short span"),Cell(row,12)==""?0:Number(Cell(row,12),"adjacent long span"),Cell(row,5)=="Elevated / cantilever edge");results.Add(result);row.Tag=result;row.Cells[13].Value=slab.Thickness.ToString("0.00");row.Cells[14].Value=result.Measures.ConcreteTotal.ToString("0.00");row.Cells[15].Value=result.Measures.FormworkTotal.ToString("0.00");row.Cells[17].Value="Estimated";}catch(Exception x){errors.Add(Cell(row,0)+" / "+Cell(row,1)+": "+x.Message);row.Cells[17].Value=x.Message;}}
  var plan=CommercialBars.Allocate(results.Select(r=>r.Steel),configuration,stockLengths);currentPlan=plan;UpdateGradeTotals();foreach(DataGridViewRow row in grid.Rows){var result=row.Tag as SlabTakeoff;if(result==null)continue;var items=plan.Where(a=>a.Entry==result.Steel).ToList();row.Cells[16].Value=items.Any(a=>a.Choice==null)?"REVIEW":items.Sum(a=>a.Purchase).ToString("0.00");}status.Text=(errors.Count>0||plan.Any(a=>a.Choice==null)?"PARTIAL | ":"")+"Concrete "+results.Sum(r=>r.Measures.ConcreteTotal).ToString("0.00")+" m3 | Forms "+results.Sum(r=>r.Measures.FormworkTotal).ToString("0.00")+" m2 | Rebar to buy "+plan.Sum(a=>a.Purchase).ToString("0.00")+" kg";review.Text=BuildReport(plan,false);if(excel!=null){timer.Stop();timer.Start();}
 }finally{filling=false;var changed=WorksChanged;if(changed!=null)changed(this,EventArgs.Empty);}ShowSelected();}
 public string Report(){Guard();grid.EndEdit();Recalculate();if(results.Count==0)throw new Exception("Add at least one valid slab estimate entry.");return BuildReport(CommercialBars.Allocate(results.Select(r=>r.Steel),configuration,stockLengths),true);}
 string BuildReport(List<StockAllocation> plan,bool extensive){var b=new StringBuilder();b.AppendLine("SLAB ESTIMATE | PURCHASE BACKUP");b.AppendLine("Report: "+mode.Text+" | "+configuration.Name);b.AppendLine("Actual materials: fc="+configuration.Input.Fc+"MPa; fy <=12="+configuration.FySmall+"MPa; fy >=16="+configuration.FyLarge+"MPa.");b.AppendLine("Commercial lengths: "+CommercialBars.FormatLengths(stockLengths)+" m");b.AppendLine("Cuts: body + 2 Ld, rounded up 25mm. No waste factor.");b.AppendLine("Blank adjacent span = current span. Count shared supports once.");if(mode.SelectedIndex==2)b.AppendLine("Unit mass kg/m: "+string.Join(", ",plan.Select(a=>a.Demand.Diameter).Distinct().OrderBy(d=>d).Select(d=>"D"+d+"="+EstimatorEngine.UnitMass(d).ToString("0.000",CultureInfo.InvariantCulture))));if(errors.Count>0||plan.Any(a=>a.Choice==null))b.AppendLine("PARTIAL / REVIEW: some entries or stock demands are excluded.");foreach(string error in errors)b.AppendLine("NOT ESTIMATED: "+error);b.AppendLine();PurchaseReports.Summary(b,plan);b.AppendLine("GROSS CONCRETE: "+results.Sum(r=>r.Measures.ConcreteTotal).ToString("0.00")+" m3 | FORMWORK: "+results.Sum(r=>r.Measures.FormworkTotal).ToString("0.00")+" m2");b.AppendLine();
  foreach(var result in results){var entry=result.Steel;var items=plan.Where(a=>a.Entry==entry).ToList();b.AppendLine();b.AppendLine(entry.Description+" | "+entry.Beam+" | "+entry.Length+" m | t="+result.Thickness.ToString("0.00")+"mm | Qty "+entry.Quantity);if(mode.SelectedIndex==0)b.AppendLine(string.Format(CultureInfo.InvariantCulture,"  Concrete {0:0.00} m3 | Forms {1:0.00} m2 | Rebar BUY {2:0.00} kg",result.Measures.ConcreteTotal,result.Measures.FormworkTotal,items.Sum(a=>a.Purchase)));if(mode.SelectedIndex>0){if(mode.SelectedIndex==2){AppendSourceSchedule(b,result);b.AppendLine(result.GeometryBasis);}b.AppendLine(string.Format(CultureInfo.InvariantCulture,"Concrete: {0:0.00} m2 x ({1:0.00}mm / 1000) x {2} panels = {3:0.00} m3",result.Measures.AreaPerPanel,result.Thickness,entry.Quantity,result.Measures.ConcreteTotal));b.AppendLine(string.Format(CultureInfo.InvariantCulture,"Forms: soffit {0:0.00}{1} = {2:0.00} m2",result.Measures.SoffitTotal,result.Measures.EdgeFormsTotal>0?" + edges "+result.Measures.EdgeFormsTotal.ToString("0.00",CultureInfo.InvariantCulture):"",result.Measures.FormworkTotal));PurchaseReports.Entry(b,items,int.Parse(entry.Quantity),mode.SelectedIndex==2);}}

  PurchaseReports.Basis(b);if(mode.SelectedIndex==2){b.AppendLine();b.AppendLine("DETAILING NOTES");foreach(string note in results.SelectMany(r=>r.Notes).Distinct())b.AppendLine(note);}
  if(extensive&&mode.SelectedIndex==2){b.AppendLine();b.AppendLine(configuration.Review());b.AppendLine(CommercialBars.Report(results.Select(r=>r.Steel),configuration,stockLengths));}return b.ToString();}
 static void AppendSourceSchedule(StringBuilder b,SlabTakeoff r){b.AppendLine(r.Schedule.Manual?"MANUAL REINFORCEMENT SCHEDULE":"ORIGINAL DXF REINFORCEMENT SCHEDULE");for(int n=0;n<SlabScheduleReader.Columns.Length;n++)b.AppendLine(string.Format("  {0,-36}{1}",SlabScheduleReader.Columns[n],r.Schedule.Bars[n]==null?"--":r.Schedule.Bars[n].Raw));}
 void UpdateGradeTotals(){gradeTotals.Rows.Clear();foreach(int grade in new[]{40,60}){var items=currentPlan.Where(a=>a.Demand.Grade==grade&&a.Choice!=null).ToList();foreach(var g in items.GroupBy(a=>a.Demand.Diameter).OrderBy(g=>g.Key))gradeTotals.Rows.Add("G"+grade,"D"+g.Key,g.Sum(a=>a.Net).ToString("0.00"),g.Sum(a=>a.Splice).ToString("0.00"),g.Sum(a=>a.Waste).ToString("0.00"),g.Sum(a=>a.Purchase).ToString("0.00"));gradeTotals.Rows.Add("G"+grade+" TOTAL","",items.Sum(a=>a.Net).ToString("0.00"),items.Sum(a=>a.Splice).ToString("0.00"),items.Sum(a=>a.Waste).ToString("0.00"),items.Sum(a=>a.Purchase).ToString("0.00"));}}
 void ShowSelected(){if(selectedDetail==null)return;var row=grid.CurrentRow;var result=row==null?null:row.Tag as SlabTakeoff;if(result==null){selectedDetail.Text=row==null?"Select a slab entry.":Cell(row,17);return;}var b=new StringBuilder();b.AppendLine(result.Steel.Description+" | "+result.Steel.Beam+" | "+result.Steel.Length+"m | Qty "+result.Steel.Quantity);AppendSourceSchedule(b,result);b.AppendLine();b.AppendLine(result.GeometryBasis);PurchaseReports.Entry(b,currentPlan.Where(a=>a.Entry==result.Steel).ToList(),int.Parse(result.Steel.Quantity),true);selectedDetail.Text=b.ToString();}
 void ChooseStock(){Guard();var selected=StockLengthPicker.Choose(this,stockLengths);if(selected!=null){stockLengths=selected;Recalculate();}}
 void EditAdvanced(){Guard();var row=grid.CurrentRow;if(row==null||row.IsNewRow)throw new Exception("Select a slab entry first.");SlabScheduleRow schedule;if(!schedules.TryGetValue(Cell(row,1),out schedule))throw new Exception("Choose a slab mark first.");using(var f=new SlabEntryOptionsForm(Cell(row,5),Enumerable.Range(6,7).Select(n=>Cell(row,n)).ToArray(),schedule)){if(f.ShowDialog(this)!=DialogResult.OK)return;filling=true;try{row.Cells[5].Value=f.SelectedType;for(int n=0;n<7;n++)row.Cells[6+n].Value=f.Values[n];}finally{filling=false;}Recalculate();}}
 void ShowCurtailment(){Guard();MessageBox.Show(this,"CURTAILED SLAB DETAILING\n\nBottom end / continuous support offset: entered span / 6.\nTop end / continuous support extension: entered span / 4.\nLocations and final cuts round UP to 25 mm.\n\nBottom curtailed body = span minus both rounded L/6 offsets.\nContinuous top body = this-panel L/4 + adjacent-panel L/4.\nStraight end allowance = 2 x computed Ld per cut piece.\nAdditional stock splices use computed lap from saved configuration.\n\nShort/long input spans are used directly; no support-width deduction.","Slab curtailment reference");}
 string State(){return Snapshot();}
 public event EventHandler WorksChanged;
 internal string[] WorksValidationIssues(){return errors.Select(e=>"Slab: "+e).Concat(WorksPlan().Where(a=>a.Choice==null).Select(a=>"Slab "+a.Entry.Beam+" / "+a.Line.Part+": unresolved stock cut; review checked commercial lengths and splice settings.")).ToArray();}
 internal List<StockAllocation> WorksPlan(){return CommercialBars.Allocate(results.Select(r=>r.Steel),configuration,stockLengths);}
 internal object[,] WorksExcelRows(List<StockAllocation> shared=null,bool requireValid=true){if(requireValid&&errors.Count>0)throw new Exception("Resolve invalid slab entries before syncing Program of Works.");var plan=shared==null?WorksPlan():shared.Where(a=>results.Any(r=>r.Steel==a.Entry)).ToList();if(requireValid&&plan.Any(a=>a.Choice==null))throw new Exception("Resolve slab stock cuts before syncing.");if(!requireValid)plan=plan.Where(a=>a.Choice!=null).ToList();var groups=plan.GroupBy(a=>new{a.Entry,a.Demand.Grade,a.Demand.Diameter}).ToList();var rows=new object[groups.Count,12];for(int n=0;n<groups.Count;n++){var g=groups[n];rows[n,0]=g.Key.Entry.Description;rows[n,1]=g.Key.Entry.Beam;rows[n,2]="Slab schedules";rows[n,3]=g.Key.Grade;rows[n,4]=g.Key.Diameter;rows[n,5]=g.Sum(a=>a.Net);rows[n,6]=0;rows[n,7]=0;rows[n,8]=g.Sum(a=>a.Splice+a.Waste);rows[n,9]=g.Sum(a=>a.Purchase);rows[n,10]=0;rows[n,11]=int.Parse(g.Key.Entry.Quantity);}return rows;}
 internal object[,] WorksMeasureRows(){var rows=new object[results.Count,8];for(int n=0;n<results.Count;n++){var r=results[n];rows[n,0]=r.Steel.Description;rows[n,1]=r.Steel.Beam;rows[n,2]=grid.Rows.Cast<DataGridViewRow>().Where(row=>object.ReferenceEquals(row.Tag,r)).Select(row=>Cell(row,5)).FirstOrDefault()??(r.Measures.SoffitTotal>0?"Elevated slab":"On gravel fill");rows[n,3]=int.Parse(r.Steel.Quantity);rows[n,4]=r.Measures.ConcreteTotal;rows[n,5]=r.Measures.EdgeFormsTotal;rows[n,6]=r.Measures.SoffitTotal;rows[n,7]=r.Measures.FormworkTotal;}return rows;}
 internal string WorksSnapshot(){grid.EndEdit();Recalculate();return sourceFiles.Count==0?null:Snapshot();}
 internal void WorksRestore(string xml){using(GridBatch.Suspend(this))Restore(xml);saved=State();}
 internal string WorksSaveState(){return State();}internal bool WorksDirty{get{return State()!=saved;}}internal void WorksSavedState(string state){saved=state;}internal void WorksSaved(){saved=State();}
 string Snapshot(){Resolve();var doc=new XmlDocument();var root=doc.CreateElement("SlabEstimate");root.SetAttribute("version","1");root.SetAttribute("stockLengths",CommercialBars.FormatLengths(stockLengths));root.SetAttribute("cover",cover.Value.ToString(CultureInfo.InvariantCulture));root.SetAttribute("report",mode.SelectedIndex.ToString());root.SetAttribute("fc",fc.Text);root.SetAttribute("small",small.SelectedIndex.ToString());root.SetAttribute("large",large.SelectedIndex.ToString());doc.AppendChild(root);var config=doc.CreateElement("Configuration");configuration.Write(config);root.AppendChild(config);foreach(var source in sourceFiles){var e=doc.CreateElement("Source");e.SetAttribute("name",source[0]);e.InnerText=source[1];root.AppendChild(e);}foreach(DataGridViewRow row in grid.Rows){if(row.IsNewRow)continue;var e=doc.CreateElement("Entry");for(int n=0;n<13;n++)e.SetAttribute("c"+n,Cell(row,n));root.AppendChild(e);}return doc.OuterXml;}
 void Restore(string xml){var doc=new XmlDocument{XmlResolver=null};using(var input=new StringReader(xml))using(var reader=XmlReader.Create(input,new XmlReaderSettings{XmlResolver=null,DtdProcessing=DtdProcessing.Prohibit,MaxCharactersInDocument=0}))doc.Load(reader);var root=doc.DocumentElement;if(root==null||root.Name!="SlabEstimate"||root.GetAttribute("version")!="1")throw new Exception("This is not a slab estimate. Use a separate slab workbook.");var parsed=new HashSet<string>(StringComparer.OrdinalIgnoreCase);foreach(XmlElement source in root.SelectNodes("Source"))foreach(var row in ManualSlabSchedule.ReadSource(source.InnerText))if(!parsed.Add(row.Mark))throw new Exception("Duplicate marks in saved slab estimate.");var restoredStock=CommercialBars.ParseLengths(root.GetAttribute("stockLengths"));var profile=LengthConfiguration.Read(root["Configuration"]);int report=int.Parse(root.GetAttribute("report")),gs=int.Parse(root.GetAttribute("small")),gl=int.Parse(root.GetAttribute("large"));decimal cv=decimal.Parse(root.GetAttribute("cover"),CultureInfo.InvariantCulture);if(report<0||report>2||gs<0||gs>1||gl<0||gl>1||cv<0||cv>100)throw new Exception("Invalid slab estimate settings.");filling=true;try{stockLengths=restoredStock;grid.Rows.Clear();schedules.Clear();sourceFiles.Clear();((DataGridViewComboBoxColumn)grid.Columns[1]).Items.Clear();foreach(XmlElement source in root.SelectNodes("Source"))AddSource(source.InnerText,source.GetAttribute("name"));fc.SelectedItem=root.GetAttribute("fc");small.SelectedIndex=gs;large.SelectedIndex=gl;cover.Value=cv;mode.SelectedIndex=report;configuration=profile;storedProfile=true;fc.Enabled=small.Enabled=large.Enabled=false;foreach(XmlElement e in root.SelectNodes("Entry")){int n=grid.Rows.Add();for(int c=0;c<13;c++)grid.Rows[n].Cells[c].Value=e.GetAttribute("c"+c);}}finally{filling=false;}Recalculate();saved=State();}
 bool SaveDialog(){Guard();grid.EndEdit();Recalculate();if(sourceFiles.Count==0)throw new Exception("Load a slab DXF or enter a manual reinforcement schedule first.");using(var d=new SaveFileDialog{Filter="Slab estimate XML|*.slab-estimate.xml",FileName="Slab-Estimate.slab-estimate.xml"}){if(d.ShowDialog(this)!=DialogResult.OK)return false;string temp=d.FileName+"."+Guid.NewGuid().ToString("N")+".tmp";try{File.WriteAllText(temp,Snapshot(),new UTF8Encoding(false));File.Copy(temp,d.FileName,true);}finally{if(File.Exists(temp))File.Delete(temp);}saved=State();return true;}}
 void Save(){SaveDialog();}void Open(){Guard();if(!ReplaceOkay())return;using(var d=new OpenFileDialog{Filter="Slab estimate XML|*.slab-estimate.xml"})if(d.ShowDialog(this)==DialogResult.OK)Restore(File.ReadAllText(d.FileName));}
 bool ReplaceOkay(){return sourceFiles.Count==0||State()==saved||MessageBox.Show(this,"Replace current slab estimate? Save current work first if needed.","Open slab estimate",MessageBoxButtons.OKCancel)==DialogResult.OK;}
 void Link(){Guard();using(var d=new SaveFileDialog{Filter="Excel macro-enabled workbook|*.xlsm|Excel workbook|*.xlsx",FileName="Slab-Summary.xlsm",OverwritePrompt=false}){if(d.ShowDialog(this)!=DialogResult.OK)return;var next=new ExcelLiveLink(d.FileName);try{string snapshot=next.ReadEstimate();bool restore=snapshot!=null;if(restore&&sourceFiles.Count>0){var answer=MessageBox.Show(this,"Load the slab estimate saved in this workbook?\\nYes: load saved estimate. No: replace workbook data with current estimate.","Slab workbook",MessageBoxButtons.YesNoCancel);if(answer==DialogResult.Cancel){next.Dispose();return;}restore=answer==DialogResult.Yes;}if(snapshot!=null){var check=new XmlDocument{XmlResolver=null};using(var input=new StringReader(snapshot))using(var reader=XmlReader.Create(input,new XmlReaderSettings{DtdProcessing=DtdProcessing.Prohibit,XmlResolver=null}))check.Load(reader);if(check.DocumentElement.Name!="SlabEstimate")throw new Exception("Use a separate Excel workbook for slabs; beam estimates were not overwritten.");}var old=excel;excel=null;try{if(restore)Restore(snapshot);else if(sourceFiles.Count==0)throw new Exception("Load a slab schedule or choose a workbook with a saved slab estimate.");}catch{excel=old;throw;}if(old!=null)old.Dispose();excel=next;Recalculate();SyncExcel();}catch{if(excel!=next)next.Dispose();throw;}}}
 void Disconnect(){timer.Stop();if(excel==null)return;try{SyncExcel();}catch(Exception x){if(MessageBox.Show(this,x.Message+"\\nDisconnect without saving latest edits?","Excel",MessageBoxButtons.YesNo)!=DialogResult.Yes)return;}excel.Dispose();excel=null;status.Text="Excel disconnected; saved workbook retained.";}
 void SyncExcel(){if(excel==null)return;Guard();var plan=CommercialBars.Allocate(results.Select(r=>r.Steel),configuration,stockLengths);if(plan.Any(a=>a.Choice==null))throw new Exception("Resolve stock cuts before Excel sync.");var groups=plan.GroupBy(a=>new{a.Entry,a.Demand.Grade,a.Demand.Diameter}).ToList();var rows=new object[groups.Count,12];for(int n=0;n<groups.Count;n++){var g=groups[n];rows[n,0]=g.Key.Entry.Description;rows[n,1]=g.Key.Entry.Beam;rows[n,2]="Slab schedules";rows[n,3]=g.Key.Grade;rows[n,4]=g.Key.Diameter;rows[n,5]=g.Sum(a=>a.Net);rows[n,6]=0;rows[n,7]=0;rows[n,8]=g.Sum(a=>a.Splice+a.Waste);rows[n,9]=g.Sum(a=>a.Purchase);rows[n,10]=0;rows[n,11]=int.Parse(g.Key.Entry.Quantity);}var concrete=new object[results.Count,8];for(int n=0;n<results.Count;n++){var r=results[n];concrete[n,0]=r.Steel.Description;concrete[n,1]=r.Steel.Beam;concrete[n,2]=r.Measures.SoffitTotal>0?"Elevated slab":"On gravel fill";concrete[n,3]=int.Parse(r.Steel.Quantity);concrete[n,4]=r.Measures.ConcreteTotal;concrete[n,5]=r.Measures.EdgeFormsTotal;concrete[n,6]=r.Measures.SoffitTotal;concrete[n,7]=r.Measures.FormworkTotal;}excel.Update(rows,(errors.Count>0?"PARTIAL | ":"")+"Slab purchase kg; Main=all slab bars; allowance=lap+offcut; forms sheet includes slab edges/soffit",Snapshot(),concrete);saved=State();status.Text="Slab Excel synced "+DateTime.Now.ToString("HH:mm:ss");}

